/// Equivalent to DotProductMetric with normalization of the vectors in preprocessing.
impl Metric<VectorElementType> for CosineMetric {
    fn distance() -> Distance { Distance::Cosine }
    fn preprocess(vector: DenseVector) -> DenseVector { ... cosine_preprocess(vector) }
}
pub fn cosine_preprocess(vector: DenseVector) -> DenseVector {
    let mut length: f32 = vector.iter().map(|x| x * x).sum();
    if is_length_zero_or_normalized(length) { return vector; }
    length = length.sqrt();
    vector.iter().map(|x| x / length).collect()      // divide by L2 norm -> stored normalized
}
