// lib/segment/src/segment/entry.rs:808-829 — CLEAR PAYLOAD touches payload index ONLY:
fn clear_payload(&mut self, op_num: SeqNumberType, point_id: PointIdType,
    hw_counter: &HardwareCounterCell) -> OperationResult<bool> {
    let internal_id = self.id_tracker.borrow().internal_id(point_id);
    self.handle_point_version_and_failure(op_num, internal_id, |segment| match internal_id {
        Some(internal_id) => {
            segment.payload_index.borrow_mut().clear_payload(internal_id, hw_counter)?;
            segment.version_tracker.set_payload(Some(op_num));
            Ok((true, Some(internal_id)))
        }
        None => Err(OperationError::PointIdError { missed_point_id: point_id }),
    })
}
